mapper.select:
select id, organization_id, doc_id, seq, content, create_time, update_time, create_user, update_user from ai_knowledge_chunk where organization_id = #{orgId}
and (
content like concat('%', #{kw}, '%')
)
order by create_time desc limit #{limit}

mapper.delete:
delete from ai_knowledge_chunk
where organization_id = #{orgId}
  and doc_id = #{docId}
